-- La bóveda responde solo sí o no: el flujo nunca ve el CBU registrado.
SELECT ($2 ~ '^\d{22}$') AS cbu_leido,
       CASE WHEN $2 ~ '^\d{22}$' THEN boveda.cbu_coincide($1, $2) ELSE false END AS coincide;

