// Señales de A06. Cualquiera de ellas frena el pago; ninguna cambia un CBU.
const e = $('CA84c_Disparador').first().json;
const b = $input.first().json;
const fin4 = (c) => c ? '...' + String(c).slice(-4) : '';
const motivos = [];
if (!b.cbu_leido) motivos.push('No se pudo leer el CBU de la factura');
else if (!b.coincide) motivos.push(`El CBU de la factura (${fin4(e.datos.cbu)}) no es el registrado para el proveedor`);
if (e.pide_cambio_cbu) motivos.push('El correo pide un cambio de cuenta bancaria' + (e.cbu_en_correo ? ` (CBU ${fin4(e.cbu_en_correo)})` : ''));
return [{ json: { alerta: motivos.length > 0, motivos } }];

const e = $('CA84c_Disparador').first().json;
const a = $('CA84c_Evaluar_senales').first().json;
let estado = e.estado, nivel = null, politica = null;
if (a.alerta) {
  const p = $('CA84c_Consultar_politica').first().json;
  nivel = p.nivel || null; politica = p.decision || null;
  // Falla segura: con alerta la factura queda bloqueada aunque el motor responda otra cosa o no responda.
  estado = $('CA84c_Bloquear_pago').first().json.estado === 'Bloqueada' ? 'Bloqueada' : 'Sin cambios: el comprobante no estaba en un estado que se pueda bloquear';
}
return [{ json: { correo_id: e.correo_id, adjunto: e.adjunto, comprobante_id: e.comprobante_id, proveedor_id: e.proveedor_id,
  estado, bloqueado: a.alerta, motivos_cbu: a.motivos, nivel, politica,
  sigue_a_aprobacion: !a.alerta && e.estado === 'Recibida', datos: e.datos } }];

const r = $input.first().json;
return [{ json: { modo: 'fin', automatizacion_id: 'A06', documento_id: r.comprobante_id,
  estado: r.bloqueado ? 'bloqueado' : 'ok', intervencion_humana: false, modelo_ia: '',
  auditar: r.bloqueado, actor: 'A06', accion: 'pago bloqueado por CBU', motivo: (r.motivos_cbu || []).join('; ') } }];
